native_forward_source.FlashAttnFunc:
@staticmethod
def forward(ctx, q, k, v, dropout_p, softmax_scale, causal, window_size, softcap, alibi_slopes, attn_mask, deterministic, return_softmax, s_aux, return_max_logit):
    if softmax_scale is None:
        softmax_scale = q.shape[-1] ** (-0.5)
    ctx.qk_headdim = q.shape[-1]
    results = _flash_attn_forward(q, k, v, dropout_p, softmax_scale, causal=causal, window_size=window_size, softcap=softcap, alibi_slopes=alibi_slopes, attn_mask=attn_mask, return_softmax=return_softmax and dropout_p > 0, s_aux=s_aux, return_max_logit=return_max_logit)
    if return_max_logit:
        out, q, k, v, out_padded, softmax_lse, S_dmask, rng_state, attn_mask, max_logit = results
    else:
        out, q, k, v, out_padded, softmax_lse, S_dmask, rng_state, attn_mask = results
    ctx.save_for_backward(q, k, v, out_padded, softmax_lse, rng_state)
    ctx.dropout_p = dropout_p
    ctx.softmax_scale = softmax_scale
    ctx.causal = causal
    ctx.window_size = window_size
    ctx.softcap = softcap
    ctx.alibi_slopes = alibi_slopes
    ctx.attn_mask = attn_mask
    ctx.deterministic = deterministic
    if not return_softmax:
        if return_max_logit:
            return (out, max_logit)
        else:
            return out
    else:
        return (out, softmax_lse, S_dmask)

